'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const S={data:null,session:'',settings:null,typesafe:null,assistant:null,works:null,view:'overview',overviewFilter:'all',activityFilter:'all',selectedEvent:null,sseState:'connecting',lastRender:0,queryHistory:[],refreshInFlight:null,refreshQueued:false,refreshQueuedLoud:false,eventSource:null,timers:[],destroyed:false,lastRefreshError:''};
const viewTitles={overview:'Now',activity:'Activity',topology:'System topology',agents:'Agents & workers',intelligence:'Operational intelligence',domains:'Systems',repositories:'Repositories',verification:'Verification',services:'Services & compute',connections:'Data sources'};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=n=>Number.isFinite(+n)?new Intl.NumberFormat().format(+n):'—';
function safeURL(v){try{const u=new URL(String(v||''),location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
const pct=n=>Number.isFinite(+n)?`${(+n).toFixed(1)}%`:'—';
const gb=n=>Number.isFinite(+n)&&+n>0?`${(+n/1073741824).toFixed(1)} GB`:'—';
const dt=v=>v?new Date(v):null;
function ago(v){const d=dt(v);if(!d||Number.isNaN(d.getTime()))return'—';const s=Math.round((Date.now()-d.getTime())/1000);if(s<0)return'in the future';if(s<45)return'just now';if(s<3600)return`${Math.floor(s/60)}m ago`;if(s<86400)return`${Math.floor(s/3600)}h ago`;if(s<604800)return`${Math.floor(s/86400)}d ago`;return d.toLocaleDateString(undefined,{month:'short',day:'numeric'});} 
function absTime(v){const d=dt(v);return d?d.toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—'}
function banner(msg='',kind=''){const b=$('#banner');if(!msg){b.className='banner hidden';b.textContent='';return}b.className=`banner ${kind}`;b.textContent=msg;}
async function api(path,opt={}){const headers={...(opt.headers||{})};if(S.session)headers['X-WarRoom-Session']=S.session;const r=await fetch(path,{...opt,headers});if(!r.ok){let t=await r.text();throw new Error(t.trim()||`${r.status} ${r.statusText}`)}const ct=r.headers.get('content-type')||'';return ct.includes('application/json')?r.json():r.text();}
function latestWorkflowRuns(runs=[]){const m=new Map();for(const w of runs){const k=`${w.repo}\0${w.name}`;const prev=m.get(k);if(!prev||new Date(w.createdAt)>new Date(prev.createdAt))m.set(k,w)}return [...m.values()].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));}
function latestObservedWorkflows(d){return latestWorkflowRuns(d.github.workflowRuns||[])}
function isBadConclusion(x=''){return['failure','timed_out','action_required','startup_failure'].includes(x)}
function isGoodConclusion(x=''){return x==='success'}
function isBadProbe(p){return p.status==='down'||p.status==='degraded'}
function countBadWorkflows(runs=[]){return runs.filter(w=>isBadConclusion(w.conclusion)).length}
function observedAgeSeconds(){if(!S.data?.github?.observedAt)return Infinity;return Math.max(0,(Date.now()-new Date(S.data.github.observedAt).getTime())/1000)}
function githubFreshnessTTLSeconds(){const reconcile=Number(S.data?.github?.reconcileSeconds||S.settings?.refreshSeconds||0);if(!Number.isFinite(reconcile)||reconcile<=0)return 900;return Math.max(180,Math.min(1800,reconcile*4))}
function githubObservationMode(){const g=S.data?.github;if(!g?.observedAt)return'unknown';const remote=g.source==='GitHub REST API'||/rest/i.test(String(g.observationMode||''));if(!remote)return(g.repos?.length||0)>0?'snapshot':'unknown';if(observedAgeSeconds()>githubFreshnessTTLSeconds())return'stale';if(S.sseState==='offline')return'offline';if(S.sseState==='reconnecting')return'reconnecting';if(S.sseState==='connecting')return'connecting';return'live'}
function connectionQuality(){return githubObservationMode()}
function setView(v){if(!viewTitles[v])return;const apply=()=>{S.view=v;$$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${v}`));$$('.nav').forEach(x=>{const active=x.dataset.view===v;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});$('#viewTitle').textContent=viewTitles[v];location.hash=v==='overview'?'':v;$('#sidebar').classList.remove('open');if(v==='activity')renderActivityView();if(v==='topology'){window.AGSpatial?.setData(S.data,connectionQuality());setTimeout(()=>window.AGSpatial?.fit(false),50)}if(v==='agents')renderAgents();if(v==='intelligence')renderIntelligence();if(v==='repositories')renderRepos();if(v==='domains')renderDomains();if(v==='verification')renderMetrics();if(v==='services')renderServices();window.AGVisual?.decorate();};window.AGVisual?.transition?window.AGVisual.transition(apply):apply();}
function totalActivity24h(){const cutoff=Date.now()-864e5;const gh=(S.data?.github?.activities||[]).filter(x=>new Date(x.timestamp).getTime()>=cutoff).length;const agents=(S.data?.agents?.events||[]).filter(x=>new Date(x.timestamp).getTime()>=cutoff).length;return gh+agents}
function sourceSummary(){const g=S.data?.github;if(!g)return'No source';if(g.authenticated)return`GitHub · ${g.identity||'authenticated'}`;if(g.source==='GitHub REST API')return'GitHub · public';return'Build snapshot';}
function systemAssessment(){const d=S.data;if(!d)return{headline:'Building current system picture…',summary:'Waiting for source-backed observations.',tone:'neutral'};const quality=connectionQuality(),latest=latestObservedWorkflows(d),fails=countBadWorkflows(latest),probeDown=(d.probes||[]).filter(p=>isBadProbe(p)).length,needs=d.needsYou||0;if(quality==='snapshot')return{headline:'System picture is a build snapshot',summary:`Showing ${fmt(d.github.repos?.length)} repositories from packaged inventory. Connect or refresh GitHub before treating this as current operational state.`,tone:'neutral'};if(quality==='stale')return{headline:'System picture is stale',summary:`Last GitHub observation was ${ago(d.github.observedAt)}. Refresh before making consequential decisions.`,tone:'warn'};if(quality==='offline'||quality==='reconnecting')return{headline:quality==='offline'?'Live update channel is offline':'Live update channel is reconnecting',summary:`Last source-backed GitHub observation was ${ago(d.github.observedAt)}. War Room will reconcile canonical state when the stream returns.`,tone:'warn'};if(needs>0)return{headline:`${needs} observed item${needs===1?'':'s'} need attention`,summary:`${fails?`${fails} latest CI failure${fails===1?'':'s'}`:'No latest CI failures'}${probeDown?` · ${probeDown} degraded service probe${probeDown===1?'':'s'}`:''}. Everything else remains evidence-bounded.`,tone:'warn'};return{headline:'No connected source is currently reporting a blocker',summary:`Observing ${fmt(d.github.repos?.length)} repositories across ${fmt(d.domains?.length)} domains. This is not a proof that every system is healthy.`,tone:'good'};}
function renderSidebar(){const d=S.data;if(!d)return;const activity=totalActivity24h(),quality=connectionQuality(),qualityLabel={live:'live',stale:'stale',snapshot:'snapshot',reconnecting:'reconnect',offline:'offline',connecting:'connecting',unknown:'unknown'}[quality]||'unknown';$('#navActivityCount').textContent=fmt(activity);if($('#navTopologyState'))$('#navTopologyState').textContent=qualityLabel;if($('#navAgentCount'))$('#navAgentCount').textContent=fmt(d.agents?.active||0);$('#navIntelligenceCount').textContent=fmt(d.intelligence?.candidates?.length||0);$('#navRepoCount').textContent=fmt(d.github.repos?.length||0);$('#navDomainCount').textContent=fmt(d.domains?.length||0);$('#navEvidenceCount').textContent=fmt(d.metrics?.length||0);const badProbes=(d.probes||[]).filter(p=>isBadProbe(p)).length;$('#navServiceState').textContent=badProbes?`${badProbes}!`:(d.probes?.length?`${d.probes.length}`:'—');const a=systemAssessment();$('#sidebarNow').textContent=a.headline;const dot=$('#connDot'), live=$('#sidebarLive .presence'), fresh=$('#freshnessDot');[dot,live,fresh].forEach(el=>{if(!el)return;el.classList.remove('good','warn','stale','offline','snapshot','reconnecting');if(quality==='live'){if(el===dot)el.classList.add('good')}else if(quality==='stale')el.classList.add(el===dot?'warn':'stale');else if(quality==='snapshot')el.classList.add('snapshot');else if(quality==='reconnecting'||quality==='connecting')el.classList.add('reconnecting');else el.classList.add('offline')});$('#connText').textContent=d.connectionState||'Unknown';$('#connectionMini').className=`connection-dot ${d.github.authenticated&&quality==='live'?'good':quality==='stale'||quality==='reconnecting'?'warn':''}`;$('#sidebarLive span:last-child').textContent={live:'Live',stale:'Stale',snapshot:'Snapshot',reconnecting:'Reconnecting',connecting:'Connecting',offline:'Offline',unknown:'Unknown'}[quality]||'Unknown';$('#freshnessText').textContent={live:'Live observation',stale:'Stale observation',snapshot:'Build snapshot',reconnecting:'Reconnecting · last observation retained',connecting:'Connecting',offline:'Offline · last observation retained',unknown:'Unobserved'}[quality]||'Unobserved';
  const domains=[...(d.domains||[])].sort((a,b)=>(b.ciFailing-a.ciFailing)||(b.activity24h-a.activity24h)).slice(0,6);$('#domainShortcuts').innerHTML='<div class="nav-label">Domains</div>'+domains.map(x=>`<button class="nav-item domain-shortcut ${esc(x.status)}" data-domain="${esc(x.name)}" aria-label="${esc(shortDomain(x.name))}"><span class="domain-signal"></span><span>${esc(shortDomain(x.name))}</span><span class="nav-meta">${x.ciFailing?`${x.ciFailing}!`:x.activity24h||''}</span></button>`).join('');$$('.domain-shortcut').forEach(b=>b.onclick=()=>{setView('repositories');$('#repoDomainFilter').value=b.dataset.domain;renderRepos()});}
function shortDomain(n){return n.replace(' & ',' / ').replace('Institution / Governance','Governance').replace('Execution / Runtime','Runtime').replace('Evidence / Verification','Evidence').replace('Integration / Capability','Integrations').replace('Intelligence / Research','Research').replace('Product / Experience','Products').replace('Infrastructure / Delivery','Infrastructure').replace('Business / Operations','Business').replace('Brand / Public Surface','Brand')}
function pulseCard(label,value,meta,cls=''){return`<div class="pulse-metric ${cls}"><span class="label">${esc(label)}</span><span class="value">${esc(value)}</span><div class="meta">${esc(meta)}</div></div>`}
function renderPulse(){const d=S.data;if(!d)return;const a=systemAssessment(),quality=connectionQuality();$('#systemHeadline').textContent=a.headline;$('#systemSummary').textContent=a.summary;$('#observedAt').textContent=`GitHub observed ${ago(d.github.observedAt)} · ${sourceSummary()}`;if($('#briefMode'))$('#briefMode').textContent=`War Room · ${{live:'live brief',stale:'stale brief',snapshot:'build snapshot',reconnecting:'reconnecting',connecting:'connecting',offline:'offline snapshot',unknown:'unobserved'}[quality]||'observed brief'}`;if($('#activityModeLabel'))$('#activityModeLabel').textContent={live:'Live activity',stale:'Stale activity snapshot',snapshot:'Snapshot activity',reconnecting:'Activity · reconnecting',connecting:'Activity · connecting',offline:'Offline activity snapshot',unknown:'Observed activity'}[quality]||'Observed activity';const latest=latestObservedWorkflows(d);const failing=countBadWorkflows(latest);const passing=latest.filter(w=>isGoodConclusion(w.conclusion)).length;const denom=passing+failing;const ciRate=denom?`${Math.round(passing/denom*100)}%`:'—';const probeUp=(d.probes||[]).filter(p=>p.status==='up').length;const repoN=d.github.repos?.length||0;$('#pulseMetrics').innerHTML=[pulseCard('Repositories',fmt(repoN),`${d.domains?.length||0} domains`),pulseCard('Activity / 24h',fmt(totalActivity24h()),`${fmt(d.github.commits24h)} commits`),pulseCard('Latest CI',ciRate,denom?`${failing} failing · ${passing} passing`:'not observed',failing?'warn':denom?'good':''),pulseCard('Needs You',fmt(d.needsYou||0),(d.needsYou||0)?'observed blockers':'none observed',(d.needsYou||0)?'warn':'good'),pulseCard('Surfaces',d.probes?.length?`${probeUp}/${d.probes.length}`:'—',d.probes?.length?'HTTP up':'not observed',probeUp===d.probes?.length&&d.probes?.length?'good':'')].join('');}
function combinedEvents(){const d=S.data;if(!d)return[];const acts=(d.github.activities||[]).map(x=>({...x,kind:x.type,when:x.timestamp,source:'GitHub'}));const flows=latestObservedWorkflows(d).map(w=>({kind:'workflow',type:'workflow',repo:w.repo,title:w.name,actor:w.event,state:w.conclusion||w.status,url:w.url,when:w.createdAt,timestamp:w.createdAt,sha:w.sha,conclusion:w.conclusion,status:w.status,branch:w.branch,source:'GitHub Actions'}));const agents=(d.agents?.events||[]).map(x=>({...x,kind:'agent_event',agentKind:x.kind,actor:x.agentId,when:x.timestamp,source:x.source||'Agent Fabric'}));return [...acts,...flows,...agents].sort((a,b)=>new Date(b.when)-new Date(a.when));}
function eventIcon(e){if(e.kind==='commit')return'↗';if(e.kind==='pull_request')return'PR';if(e.kind==='issue')return'#';if(e.kind==='workflow')return isBadConclusion(e.conclusion)?'!':'✓';if(e.kind==='agent_event')return'◉';return'·'}
function eventMeta(e){if(e.kind==='workflow')return [e.repo,e.branch,e.actor,e.conclusion||e.status].filter(Boolean);if(e.kind==='agent_event')return [e.actor,e.repo,e.agentKind,e.state].filter(Boolean);return [e.repo,e.actor,e.sha,e.state].filter(Boolean)}
function feedFilter(events,filter){if(filter==='all')return events;if(filter==='changes')return events.filter(e=>['commit','pull_request','issue'].includes(e.kind));if(filter==='ci')return events.filter(e=>e.kind==='workflow');if(filter==='agents')return events.filter(e=>e.kind==='agent_event');return events.filter(e=>e.kind===filter)}
function eventHTML(e,index){const cls=e.kind==='workflow'?`workflow ${isBadConclusion(e.conclusion)?'bad':isGoodConclusion(e.conclusion)?'good':''}`:e.kind;return`<div class="timeline-item" data-event-index="${index}" data-event-time="${esc(e.when||'')}" tabindex="0"><div class="timeline-icon ${cls}">${esc(eventIcon(e))}</div><div class="timeline-copy"><div class="timeline-title">${esc(e.title||'Untitled event')}</div><div class="timeline-meta">${eventMeta(e).map((m,i)=>`<span class="${i===0?'repo-name':''}">${esc(m)}</span>`).join('<span>·</span>')}</div></div><time class="timeline-time" title="${esc(absTime(e.when))}">${ago(e.when)}</time></div>`}
function renderLiveFeed(){const all=combinedEvents();let events=feedFilter(all,S.overviewFilter).slice(0,18);$('#liveFeed').innerHTML=events.length?events.map((e,i)=>eventHTML(e,i)).join(''):`<div class="timeline-empty">No activity observed for this filter. Connect GitHub and sync.</div>`;$('#liveFeed')._events=events;bindTimeline('#liveFeed');}
function bindTimeline(sel){const root=$(sel);root.querySelectorAll('.timeline-item').forEach(el=>{const open=()=>{const e=root._events?.[+el.dataset.eventIndex];if(!e)return;S.selectedEvent=e;if(S.view==='activity')renderActivityInspector(e);else showQueryResult(`Inspect ${e.repo}`,describeEvent(e),e.url?[{label:'Open source',url:e.url}]:[])};el.onclick=open;el.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();open()}}})}
function describeEvent(e){if(e.kind==='workflow')return`${e.repo} / ${e.title} on ${e.branch||'unknown branch'} is ${e.conclusion||e.status||'unknown'}. Observed ${ago(e.when)} from GitHub Actions${e.sha?` at ${e.sha}`:''}.`;if(e.kind==='agent_event')return`${e.actor||'Agent'} reported ${e.agentKind||'activity'}${e.repo?` for ${e.repo}`:''}: ${e.title}. State: ${e.state||'unobserved'}. Observed ${ago(e.when)} from ${e.source||'Agent Fabric'}.`;return`${e.kind.replace('_',' ')} in ${e.repo}: ${e.title}${e.actor?` by ${e.actor}`:''}${e.sha?` at ${e.sha}`:''}. Observed ${ago(e.when)}.`}
function renderAttention(){const d=S.data;if(!d)return;const items=[];for(const w of latestObservedWorkflows(d)){if(isBadConclusion(w.conclusion))items.push({kind:'bad',title:`${w.repo} · ${w.name}`,meta:`${w.conclusion} · ${ago(w.createdAt)}`,url:w.url})}for(const p of d.probes||[]){if(isBadProbe(p))items.push({kind:p.status==='down'?'bad':'warn',title:p.name,meta:`${p.status}${p.httpStatus?` · HTTP ${p.httpStatus}`:''}`,url:p.url})}for(const a of d.agents?.sessions||[]){if(a.state==='blocked')items.push({kind:'warn',title:`${a.name} · blocked`,meta:[a.currentAction,a.repo,`heartbeat ${ago(a.lastHeartbeat)}`].filter(Boolean).join(' · '),url:a.url})}$('#needsCount').textContent=items.length;$('#needsCountTop').textContent=items.length;$('#attention').innerHTML=items.length?items.slice(0,8).map(x=>`<a class="attention-item" href="${esc(safeURL(x.url))}" ${x.url?'target="_blank" rel="noreferrer"':''}><span class="signal ${esc(x.kind)}"></span><div><div class="item-title">${esc(x.title)}</div><div class="item-meta">${esc(x.meta)}</div></div><span class="row-value">${x.url?'↗':'!'}</span></a>`).join(''):`<div class="empty-state compact"><b>No observed blockers.</b><span>Connected evidence currently has no item that requires your intervention.</span></div>`;}
function renderContext(){const d=S.data;if(!d)return;const host=d.host||{},quality=connectionQuality();$('#routineSyncStatus')?.classList.toggle('live',quality==='live');$('#routineIntelStatus')?.classList.toggle('live',!!d.intelligence?.generatedAt);const latest=latestObservedWorkflows(d);const fail=countBadWorkflows(latest);const agents=d.agents||{};const rows=[{s:connectionQuality()==='live'?'good':'warn',k:'GitHub',v:sourceSummary(),m:`${ago(d.github.observedAt)} · ${S.settings?.refreshSeconds||60}s reconcile`},{s:fail?'bad':latest.length?'good':'warn',k:'CI',v:latest.length?`${latest.length} latest workflows`:'Unobserved',m:fail?`${fail} need attention`:'No latest failure observed'},{s:agents.blocked?'bad':agents.active?'good':'warn',k:'Agent Fabric',v:agents.active?`${agents.active} active · ${agents.running||0} running`:'No live sessions',m:agents.blocked?`${agents.blocked} blocked`:`${agents.stale||0} stale`},{s:host.observedAt?'good':'warn',k:'This computer',v:host.hostname||`${host.os||'local'} host`,m:host.observedAt?`${pct(host.cpuPercent)} CPU · ${pct(host.memoryUsedPercent)} memory`:'Waiting for telemetry'}];$('#liveContext').innerHTML=rows.map(x=>`<div class="context-row"><span class="signal ${x.s}"></span><div><div class="item-title">${esc(x.k)} · ${esc(x.v)}</div><div class="item-meta">${esc(x.m)}</div></div><span class="row-value">${x.s==='good'?'OK':x.s==='bad'?'!':'—'}</span></div>`).join('');$('#instIdentity').textContent=d.github.authenticated?(d.github.identity||'Authenticated'):'Unobserved';$('#instEvidence').textContent=d.metrics?.length?'Observed':'Partial';}
function agentStateClass(state=''){return state==='running'?'good':state==='blocked'?'bad':state==='stale'||state==='offline'?'warn':state==='waiting'?'cyan':''}
function renderAgentFabricMini(){const root=$('#agentFabricMini'),d=S.data?.agents;if(!root||!d)return;const live=(d.sessions||[]).filter(x=>!['stale','offline'].includes(x.state)).slice(0,4);root.innerHTML=live.length?live.map(x=>`<button class="mini-agent" data-agent-open="${esc(x.id)}"><span class="agent-state-dot ${agentStateClass(x.state)}"></span><div><b>${esc(x.name)}</b><small>${esc([x.provider,x.currentAction||x.state].filter(Boolean).join(' · '))}</small></div><span>${esc(x.state)}</span></button>`).join(''):`<div class="empty-state compact"><b>No live agent heartbeat yet.</b><span>Agent Bridge and WORKS SSE are ready.</span></div>`;root.querySelectorAll('[data-agent-open]').forEach(b=>b.onclick=()=>setView('agents'))}
function renderAssistantStatus(){const st=S.data?.assistant||S.assistant||{};const b=$('#assistantBadge');if(b){b.textContent=st.localModelAvailable?`Local · ${st.localModel||'model'}`:'Grounded core';b.classList.toggle('neutral',!st.localModelAvailable)}const msg=$('#assistantConnMsg');if(msg){msg.textContent=st.localModelAvailable?`Grounded core + ${st.localModel}. Model prose stays advisory and receives only bounded War Room context.`:`Grounded deterministic assistant is active. ${st.error?`Local model: ${st.error}. `:''}No assistant output grants authority or verification.`}}

function renderTypeSafe(){
  const root=$('#typesafeDecision'), badge=$('#typesafeBadge'), connBadge=$('#typesafeConnBadge'), btn=$('#typesafeEvaluate'), card=$('#typesafeCard');
  if(!root||!badge||!btn)return;
  const summaryDecision=S.data?.typeSafe||{};const t=S.typesafe||{};const d=(summaryDecision.evaluatedAt||summaryDecision.error||summaryDecision.route)?summaryDecision:(t.decision||t);
  const configured=!!(summaryDecision.configured||t.configured||d.configured);
  if(card)card.dataset.native=String(configured);
  badge.textContent=configured?(d.mode==='budget-paused'?'Jev · budget paused':'Jev · native'):'Activate Jev';
  badge.classList.toggle('neutral',!configured);if(connBadge){connBadge.textContent=configured?'Native':'Not configured';connBadge.classList.toggle('neutral',!configured)}
  btn.disabled=false;btn.innerHTML=configured?'<span data-icon="sparkle" data-icon-size="14"></span> Evaluate now':'<span data-icon="key" data-icon-size="14"></span> Activate native Jev';window.AGIcons?.hydrate(btn);
  if(!configured){root.innerHTML='<div class="empty-state compact"><b>Native Jev is ready to activate.</b><span>Add the API key once; Windows DPAPI stores it and the decision fabric runs automatically when observed state changes.</span></div>';return}
  if(d.error){root.innerHTML=`<div class="typesafe-error"><b>Jev provider unavailable</b><span>${esc(d.error)}</span></div><div class="typesafe-native-strip"><div><span>mode</span><b>${esc(d.mode||'native-auto')}</b></div><div><span>calls today</span><b>${fmt(d.callsToday||0)}</b></div><div><span>budget</span><b>${fmt(d.budgetRemaining??'—')}</b></div></div>`;return}
  if(!d.evaluatedAt||!d.route){root.innerHTML='<div class="empty-state compact"><b>Native decision fabric armed.</b><span>The next material system-state change can trigger Jev automatically. Manual evaluation remains available for inspection.</span></div>';return}
  const probs=d.routeProbabilities||{}, entries=Object.entries(probs).sort((a,b)=>b[1]-a[1]);
  const sevLegend=d.severityLegend||{}; const sev=Math.max(0,Math.min(3,Math.round(+d.severityScore||0))); const sevName=sevLegend[String(sev)]||['Nominal','Watch','Degraded','Critical'][sev]||'—';
  root.innerHTML=`<div class="typesafe-result">
    <div class="typesafe-route"><span class="decision-orb route-${esc(d.route)}"></span><div><small>NATIVE ROUTE</small><b>${esc(String(d.route).replaceAll('_',' '))}</b></div><strong>${Math.round((+d.routeConfidence||0)*100)}%</strong></div>
    <div class="decision-meter"><div><span>Human review</span><b>${Math.round((+d.humanNeeded||0)*100)}%</b></div><div class="prob-track"><i data-meter-width="${Math.round((+d.humanNeeded||0)*100)}"></i></div></div>
    <div class="decision-meter"><div><span>Evidence sufficiency · model judgment</span><b>${Math.round((+d.evidenceSufficient||0)*100)}%</b></div><div class="prob-track evidence"><i data-meter-width="${Math.round((+d.evidenceSufficient||0)*100)}"></i></div></div>
    <div class="decision-meter severity"><div><span>Severity</span><b>${esc(sevName)} · ${(+d.severityScore||0).toFixed(2)}</b></div><div class="severity-dots">${[0,1,2,3].map(i=>`<i class="${i<=sev?'on':''}"></i>`).join('')}</div></div>
    <div class="typesafe-native-strip"><div><span>dominant signal</span><b>${esc((d.dominantSignal||'none').replaceAll('_',' '))}</b></div><div><span>latency</span><b>${d.latencyMs?`${fmt(d.latencyMs)} ms`:'—'}</b></div><div><span>budget left</span><b>${Number.isFinite(+d.budgetRemaining)?fmt(d.budgetRemaining):'—'}</b></div></div>
    <div class="typesafe-probs">${entries.slice(0,4).map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><b>${Math.round((+v||0)*100)}%</b></div>`).join('')}</div>
    <div class="typesafe-foot"><span>${esc(d.model||'jev-latest')}</span><span>${fmt(d.inputTokens||0)} input tokens</span><span>${esc(d.mode||'native-auto')}</span><span>${ago(d.evaluatedAt)}</span></div>
  </div>`;
  root.querySelectorAll('[data-meter-width]').forEach(el=>{const v=Math.max(0,Math.min(100,Number(el.dataset.meterWidth)||0));el.style.width=`${v}%`});
}
async function loadTypeSafeStatus(){try{S.typesafe=await api('/api/typesafe/connection');renderTypeSafe()}catch{S.typesafe={configured:!!S.data?.typeSafe?.configured};renderTypeSafe()}}
async function evaluateTypeSafe(){const b=$('#typesafeEvaluate');if(!b||b.disabled)return;if(!(S.typesafe?.configured||S.data?.typeSafe?.configured)){setView('connections');setTimeout(()=>$('#typesafeApiKey')?.focus(),180);window.AGVisual?.audio('open');return}const old=b.innerHTML;b.disabled=true;b.classList.add('thinking');b.innerHTML='<span class="decision-spinner"></span> Evaluating…';window.AGVisual?.audio('tap');try{const d=await api('/api/typesafe/evaluate',{method:'POST'});S.typesafe={...(S.typesafe||{}),configured:true,decision:d};if(S.data)S.data.typeSafe=d;renderTypeSafe();window.AGVisual?.audio('success')}catch(e){S.typesafe={...(S.typesafe||{}),configured:true,decision:{error:e.message,evaluatedAt:new Date().toISOString()}};renderTypeSafe()}finally{b.disabled=false;b.classList.remove('thinking');renderTypeSafe()}}

function renderActivityView(){if(!S.data)return;const events=feedFilter(combinedEvents(),S.activityFilter);$('#activityFeed').innerHTML=events.length?events.map((e,i)=>eventHTML(e,i)).join(''):'<div class="timeline-empty">No matching events observed.</div>';$('#activityFeed')._events=events;bindTimeline('#activityFeed');if(S.selectedEvent)renderActivityInspector(S.selectedEvent)}
function renderActivityInspector(e){$('#activityInspector').innerHTML=`<span class="mini-label">${esc((e.source||e.kind).toUpperCase())}</span><h3>${esc(e.title)}</h3><p>${esc(describeEvent(e))}</p><dl class="inspector-grid"><dt>Repository</dt><dd>${esc(e.repo||'—')}</dd><dt>Type</dt><dd>${esc(e.kind||'—')}</dd><dt>Actor / event</dt><dd>${esc(e.actor||'—')}</dd><dt>State</dt><dd>${esc(e.conclusion||e.state||e.status||'—')}</dd><dt>SHA</dt><dd class="mono">${esc(e.sha||'—')}</dd><dt>Observed</dt><dd>${esc(absTime(e.when))}</dd></dl>${e.url?`<a class="inspector-link" href="${esc(safeURL(e.url))}" target="_blank" rel="noreferrer">Open source ↗</a>`:''}`}
function scorePct(v){return Number.isFinite(+v)?`${Math.round(+v*100)}%`:'—'}
function candidateFeatureMap(c){const out={};for(const f of c.features||[])out[f.name]=f.value;return out}
function renderIntelligenceTop(){const root=$('#intelligenceTop'), intel=S.data?.intelligence;if(!root)return;const c=intel?.top;if(!c){root.innerHTML='<div class="empty-state compact"><b>No ranked attention candidate.</b><span>The engine is observing. Silence is not treated as verified health.</span></div>';return}root.innerHTML=`<button class="next-move" data-open-intelligence="1"><div class="next-move-line"><span class="risk-orb ${c.priorityScore>=70?'bad':c.priorityScore>=45?'warn':''}"></span><span>${esc(c.title)}</span><b>${Math.round(c.priorityScore)}</b></div><p>${esc(c.recommendedAction)}</p><div class="next-move-meta"><span>${esc(c.scope)}</span><span>risk ${scorePct(c.riskScore)}</span><span>confidence ${scorePct(c.confidence)}</span></div></button>`;root.querySelector('[data-open-intelligence]')?.addEventListener('click',()=>setView('intelligence'))}
function featureHTML(f){const mag=Math.min(100,Math.abs(f.contribution||0)/3*100);return`<div class="feature-row" title="${esc(f.evidence)}"><div><span>${esc(f.name.replaceAll('_',' '))}</span><small>${Math.round((f.value||0)*100)}%</small></div><div class="feature-track"><i data-feature-width="${mag}"></i></div><code>${(f.contribution||0).toFixed(2)}</code></div>`}
function candidateHTML(c,i){const cls=c.priorityScore>=70?'high':c.priorityScore>=45?'medium':'low';return`<article class="candidate ${cls}" data-candidate-index="${i}"><div class="candidate-rank">${i+1}</div><div class="candidate-body"><div class="candidate-head"><div><span class="mini-label">${esc(c.kind.replaceAll('_',' '))} · ${esc(c.domain)}</span><h3>${esc(c.title)}</h3></div><div class="candidate-score"><b>${Math.round(c.priorityScore)}</b><span>priority</span></div></div><p>${esc(c.summary)}</p><div class="candidate-action"><span>Next</span>${esc(c.recommendedAction)}</div><details><summary>Why this ranked here</summary><div class="feature-list">${(c.features||[]).slice(0,5).map(featureHTML).join('')}</div><div class="evidence-tags">${(c.evidence||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div></details><div class="candidate-foot"><div><span>risk ${scorePct(c.riskScore)}</span><span>confidence ${scorePct(c.confidence)}</span><span>${esc(c.learningState)}</span></div><div class="feedback"><button data-feedback="1" data-id="${esc(c.id)}">Relevant</button><button data-feedback="0" data-id="${esc(c.id)}">Noise</button>${c.url?`<a href="${esc(safeURL(c.url))}" target="_blank" rel="noreferrer">Source ↗</a>`:''}</div></div></div></article>`}
async function sendIntelligenceFeedback(id,relevant){const c=S.data?.intelligence?.candidates?.find(x=>x.id===id);if(!c)return;try{await api('/api/intelligence/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidateId:id,shouldHaveAttention:relevant,features:candidateFeatureMap(c)})});banner(`Feedback recorded. Ranking model updated.`, 'ok');await refresh(true);setTimeout(()=>banner(''),1600)}catch(e){banner(e.message)}}
function renderIntelligence(){const intel=S.data?.intelligence;if(!intel)return;$('#intelligenceMode').textContent=`${intel.learningState} · ${intel.feedbackCount} labels`;$('#intelligenceCount').textContent=`${intel.candidates?.length||0} candidates`;$('#intelligenceCandidates').innerHTML=(intel.candidates||[]).length?(intel.candidates||[]).map(candidateHTML).join(''):'<div class="empty-state"><b>No material attention candidate.</b><span>The ranker is still active, but current signals do not cross the display threshold.</span></div>';$('#intelligenceCandidates').querySelectorAll('[data-feature-width]').forEach(i=>i.style.width=`${Math.max(0,Math.min(100,+i.dataset.featureWidth||0))}%`);$('#intelligenceCandidates').querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>sendIntelligenceFeedback(b.dataset.id,b.dataset.feedback==='1'));const m=intel.model||{};const weights=Object.entries(m.weights||{}).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,7);$('#intelligenceModel').innerHTML=`<div class="model-stat"><span>Mode</span><b>${esc(intel.mode||'—')}</b></div><div class="model-stat"><span>State</span><b>${esc(intel.learningState||'—')}</b></div><div class="model-stat"><span>Feedback</span><b>${fmt(intel.feedbackCount||0)}</b></div><div class="model-stat"><span>Learning rate</span><b>${Number.isFinite(+m.learningRate)?(+m.learningRate).toFixed(2):'—'}</b></div><div class="weight-list">${weights.map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><code>${(+v).toFixed(2)}</code></div>`).join('')}</div><p class="model-note">Weights are adaptive ranking parameters, not policy rules or calibrated defect probabilities.</p>`;$('#intelligenceDomains').innerHTML=(intel.domains||[]).length?intel.domains.map(d=>`<div class="domain-risk"><div><span>${esc(shortDomain(d.name))}</span><small>${fmt(d.candidates)} candidates · ${scorePct(d.confidence)} confidence</small></div><b>${scorePct(d.riskScore)}</b></div>`).join(''):'<div class="empty-state compact"><b>No ranked domain risk.</b><span>Awaiting material signals.</span></div>';$('#intelligenceGuardrails').innerHTML=(intel.guardrails||[]).map(g=>`<div><span class="guardrail-mark">✓</span><span>${esc(g)}</span></div>`).join('')}
function renderAgents(){const a=S.data?.agents;if(!a)return;$('#agentObserved').textContent=a.observedAt?`Observed ${ago(a.observedAt)}`:'Unobserved';$('#agentObserved').classList.toggle('neutral',!a.active);$('#agentStats').innerHTML=[metricCard('Active',fmt(a.active||0),'fresh heartbeat / source observation',a.active?'good':''),metricCard('Running',fmt(a.running||0),'currently executing',a.running?'good':''),metricCard('Waiting',fmt(a.waiting||0),'ready / idle / queued'),metricCard('Blocked',fmt(a.blocked||0),'requires attention',a.blocked?'warn':''),metricCard('Stale',fmt(a.stale||0),`>${S.settings?.agentStaleSeconds||45}s without heartbeat`,a.stale?'warn':'')].join('');const sessions=[...(a.sessions||[])].sort((x,y)=>{const rank={blocked:0,running:1,waiting:2,idle:3,stale:4,offline:5};return (rank[x.state]??9)-(rank[y.state]??9)||new Date(y.lastHeartbeat)-new Date(x.lastHeartbeat)});$('#agentRosterCount').textContent=`${sessions.length} observed`;$('#agentRoster').innerHTML=sessions.length?sessions.map(x=>`<article class="agent-row state-${esc(x.state)}"><div class="agent-avatar-mini"><span class="agent-state-dot ${agentStateClass(x.state)}"></span></div><div class="agent-row-main"><div class="agent-row-head"><b>${esc(x.name)}</b><span class="source-chip ${['stale','offline'].includes(x.state)?'neutral':''}">${esc(x.state)}</span></div><p>${esc([x.provider,x.node,x.repo].filter(Boolean).join(' · ')||'Observed agent')}</p>${x.currentAction?`<div class="agent-action">${esc(x.currentAction)}</div>`:''}${x.progress>0?`<div class="agent-progress"><i data-progress-width="${Math.round(Math.max(0,Math.min(1,+x.progress||0))*100)}"></i></div>`:''}<div class="agent-row-foot"><span>${x.model?`model ${esc(x.model)}`:'deterministic / unreported model'}</span><span>heartbeat ${ago(x.lastHeartbeat)}</span>${x.workId?`<span>${esc(x.workId)}</span>`:''}</div></div>${x.url?`<a class="agent-source-link" href="${esc(safeURL(x.url))}" target="_blank" rel="noreferrer">↗</a>`:''}</article>`).join(''):`<div class="empty-state"><b>No agent sessions observed.</b><span>Connect WORKS or post a heartbeat through the Agent Bridge. Unobserved agents are not shown as offline.</span></div>`;$('#agentRoster').querySelectorAll('[data-progress-width]').forEach(el=>{const v=Math.max(0,Math.min(100,Number(el.dataset.progressWidth)||0));el.style.width=`${v}%`});const sources=a.sources||[];$('#agentSources').innerHTML=sources.length?sources.map(x=>`<div class="status-row"><span class="signal ${x.status==='live'?'good':x.status==='error'?'bad':'warn'}"></span><div><div class="item-title">${esc(x.name)}</div><div class="item-meta">${esc(x.kind)}${x.lastObservedAt?` · ${ago(x.lastObservedAt)}`:''}${x.error?` · ${x.error}`:''}</div></div><span class="source-chip ${x.status==='live'?'':'neutral'}">${esc(x.status)}</span></div>`).join(''):`<div class="empty-state compact"><b>No execution source connected.</b><span>Agent Bridge is ready locally; WORKS can be attached in Connections.</span></div>`;const evs=(a.events||[]).slice(0,16).map(x=>({...x,kind:'agent_event',agentKind:x.kind,actor:x.agentId,when:x.timestamp,source:x.source||'Agent Fabric'}));$('#agentEvents').innerHTML=evs.length?evs.map((e,i)=>eventHTML(e,i)).join(''):'<div class="timeline-empty">No agent events observed yet.</div>';$('#agentEvents')._events=evs;bindTimeline('#agentEvents');}
function renderServiceAgentFabric(){const root=$('#serviceAgentFabric'),a=S.data?.agents;if(!root||!a)return;const works=(a.sources||[]).find(x=>x.id==='works');root.innerHTML=`<div class="fabric-summary"><div><span class="signal ${a.blocked?'bad':a.active?'good':'warn'}"></span><div><b>${a.active||0} active execution principals</b><small>${a.running||0} running · ${a.waiting||0} waiting · ${a.blocked||0} blocked · ${a.stale||0} stale</small></div></div><div><span>WORKS</span><b>${esc(works?.status||'not connected')}</b></div><div><span>Bridge</span><b>aftergraph.agent.heartbeat/0.1</b></div></div>`}

function renderDomains(){const items=S.data?.domains||[];$('#domainGrid').innerHTML=items.map(x=>`<div class="domain-card ${esc(x.status)}" data-domain="${esc(x.name)}"><div class="domain-top"><div class="name">${esc(x.name)}</div><span class="status-chip">${esc(x.status)}</span></div><div class="domain-stats"><div><b>${fmt(x.repoCount)}</b><span>repos</span></div><div><b>${fmt(x.activity24h)}</b><span>24h events</span></div><div><b>${fmt(x.ciFailing)}</b><span>CI failing</span></div></div><div class="domain-foot">${x.openIssues?`${fmt(x.openIssues)} open issues observed`:'Issue count not fully observed'}</div></div>`).join('');$$('.domain-card').forEach(c=>c.onclick=()=>{setView('repositories');$('#repoDomainFilter').value=c.dataset.domain;renderRepos()});}
function renderRepoFilters(){const select=$('#repoDomainFilter');if(select.options.length>1)return;for(const d of S.data?.domains||[]){const o=document.createElement('option');o.value=d.name;o.textContent=d.name;select.appendChild(o)}}
function renderRepos(){if(!S.data)return;renderRepoFilters();const q=($('#repoSearch')?.value||'').trim().toLowerCase(), domain=$('#repoDomainFilter')?.value||'all';let repos=[...(S.data.github.repos||[])];if(q)repos=repos.filter(r=>`${r.name} ${r.domain}`.toLowerCase().includes(q));if(domain!=='all')repos=repos.filter(r=>r.domain===domain);repos.sort((a,b)=>new Date(b.pushedAt||0)-new Date(a.pushedAt||0)||a.name.localeCompare(b.name));$('#repoTable').innerHTML=repos.length?repos.map(r=>`<tr><td><a href="${esc(safeURL(r.htmlUrl))}" target="_blank" rel="noreferrer" class="repo-link">${esc(r.name)}</a></td><td>${esc(r.domain)}</td><td><span class="vis">${esc(r.visibility||(r.private?'private':'public'))}</span></td><td>${r.pushedAt?ago(r.pushedAt):'—'}</td><td>${r.source==='GitHub live'?fmt(r.openIssues):'—'}</td><td class="evidence-source">${esc(r.source)}</td></tr>`).join(''):`<tr><td colspan="6" class="muted">No matching repositories.</td></tr>`;}
function metricCard(name,value,meta,cls=''){return`<div class="metric-card ${cls}"><div class="metric-name">${esc(name)}</div><div class="metric-value">${esc(value)}</div><div class="metric-meta">${esc(meta)}</div></div>`}
function renderMetrics(){if(!S.data)return;const items=S.data.metrics||[], wanted=['VSR','FCR','CRR','UAR','CPVO','ControlPlaneTax','TVO','EvidenceCompleteness'], by={};for(const x of items)by[x.name]=x;$('#researchKpis').innerHTML=wanted.map(n=>{const x=by[n];if(!x)return metricCard(n,'—','not observed');let val=(x.unit==='ratio'||x.unit==='%')?`${(x.unit==='ratio'?x.value*100:x.value).toFixed(1)}%`:x.unit?`${x.value} ${x.unit}`:String(x.value), cls='';if(n==='FCR'||n==='UAR')cls=x.value===0?'good':'warn';if(n==='VSR'||n==='EvidenceCompleteness')cls='good';return metricCard(n,val,`${x.source} · ${ago(x.observedAt)}`,cls)}).join('');$('#metricTable').innerHTML=items.length?items.map(x=>`<tr><td><code>${esc(x.name)}</code></td><td>${esc(x.value)} ${esc(x.unit||'')}</td><td>${esc(x.domain||'—')}</td><td>${esc(x.source)}</td><td>${ago(x.observedAt)}</td><td>${x.evidence?`<code>${esc(x.evidence)}</code>`:'—'}</td></tr>`).join(''):`<tr><td colspan="6">No external KPI samples ingested yet.</td></tr>`;}
function renderServices(){if(!S.data)return;const ps=S.data.probes||[];$('#probeList').innerHTML=ps.length?ps.map(p=>`<div class="status-row"><span class="signal ${p.status==='up'?'good':p.status==='down'?'bad':'warn'}"></span><div><div class="item-title">${esc(p.name)}</div><div class="item-meta">${esc(p.url)} · ${p.latencyMs||0}ms · ${ago(p.observedAt)}</div></div><span class="source-chip ${p.status==='up'?'':'neutral'}">${esc(p.status)}${p.httpStatus?` ${p.httpStatus}`:''}</span></div>`).join(''):`<div class="empty-state compact"><b>No service probes yet.</b><span>Run a probe to create an observation.</span></div>`;renderHost(S.data.host)}
function renderHost(h){if(!h||!h.observedAt){$('#hostTelemetry').innerHTML='<div class="empty-state compact"><b>Waiting for host telemetry.</b><span>The desktop collector publishes every 15 seconds.</span></div>';return}const stat=(k,v,p)=>`<div class="host-stat"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div>${p==null?'':`<progress class="meter ${p>90?'bad':p>75?'warn':''}" max="100" value="${Math.max(0,Math.min(100,p))}"></progress>`}</div>`;$('#hostSource').textContent=`${h.source} · ${ago(h.observedAt)}`;$('#hostTelemetry').innerHTML=stat('CPU',pct(h.cpuPercent),h.cpuPercent<0?null:h.cpuPercent)+stat('Memory',pct(h.memoryUsedPercent),h.memoryUsedPercent)+stat('Disk C:',pct(h.diskUsedPercent),h.diskUsedPercent)+stat('Memory free',gb(h.memoryFreeBytes),null)+stat('Host',h.hostname||`${h.os}/${h.arch}`,null)+stat('War Room heap',gb(h.goHeapBytes),null)}
function renderClock(){const d=new Date();$('#clock').textContent=d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(S.data){$('#observedAt').textContent=`GitHub observed ${ago(S.data.github.observedAt)} · ${sourceSummary()}`;renderSidebar()}}
function renderOverviewFilters(){$$('#overviewFilter button').forEach(b=>b.classList.toggle('selected',b.dataset.filter===S.overviewFilter));$$('#activityFilter button').forEach(b=>b.classList.toggle('selected',b.dataset.filter===S.activityFilter))}
function render(){if(!S.data)return;S.lastRender=Date.now();renderSidebar();renderPulse();renderLiveFeed();renderAttention();renderIntelligenceTop();renderContext();renderTypeSafe();renderAgentFabricMini();renderAssistantStatus();renderOverviewFilters();renderDomains();renderRepos();renderMetrics();renderServices();renderServiceAgentFabric();if(S.view==='activity')renderActivityView();if(S.view==='agents')renderAgents();if(S.view==='intelligence')renderIntelligence();window.AGIcons?.hydrate();window.AGVisual?.decorate();const observationMode=connectionQuality();window.AGVisual?.setData(S.data,observationMode);window.AGSpatial?.setData(S.data,observationMode);}
function queryWarRoom(q){const d=S.data, t=q.toLowerCase().trim();if(!d)return{answer:'System data is not loaded yet.',links:[]};const events=combinedEvents(), latest=latestObservedWorkflows(d), fails=latest.filter(w=>isBadConclusion(w.conclusion));if(/attention|need(s)? you|block|problem|fail/.test(t)){if(!d.needsYou)return{answer:'No connected source currently reports an item that needs intervention. That is an observed-state statement, not a proof of full organizational health.',links:[{label:'Open Services',view:'services'}]};return{answer:`${d.needsYou} observed item${d.needsYou===1?'':'s'} need attention. ${fails.length?`${fails.length} are latest CI failures: ${fails.slice(0,3).map(x=>`${x.repo}/${x.name}`).join(', ')}.`:''}`,links:[{label:'Open Activity',view:'activity'},{label:'Open Services',view:'services'}]}}
  if(/changed|today|recent|activity/.test(t)){const cutoff=Date.now()-864e5, xs=events.filter(e=>new Date(e.when).getTime()>=cutoff);return{answer:`I can currently see ${xs.length} timeline events in the last 24 hours from connected GitHub evidence. ${xs.slice(0,4).map(e=>`${e.repo}: ${e.title}`).join(' · ')||'No recent events are present in the current snapshot.'}`,links:[{label:'Open Activity',view:'activity'}]}}
  if(/ci|workflow|action/.test(t)){if(!latest.length)return{answer:'No workflow runs are present in the current evidence snapshot.',links:[{label:'Connect GitHub',view:'connections'}]};return{answer:`${fails.length} of ${latest.length} latest observed workflows are failing. ${fails.slice(0,5).map(x=>`${x.repo}/${x.name} (${x.conclusion})`).join(' · ')||'No latest workflow failure is observed.'}`,links:[{label:'Open Activity',view:'activity'}]}}
  if(/repo/.test(t)){const sorted=[...(d.github.repos||[])].sort((a,b)=>new Date(b.pushedAt||0)-new Date(a.pushedAt||0));return{answer:`War Room knows ${sorted.length} repositories. ${sorted.filter(r=>r.pushedAt).slice(0,5).map(r=>`${r.name} (${ago(r.pushedAt)})`).join(' · ')||'Push timestamps are not present in the build snapshot.'}`,links:[{label:'Open Repositories',view:'repositories'}]}}
  if(/service|surface|website|docs/.test(t)){const ps=d.probes||[];return{answer:ps.length?ps.map(p=>`${p.name}: ${p.status}${p.httpStatus?` HTTP ${p.httpStatus}`:''}`).join(' · '):'No service probes have been observed yet.',links:[{label:'Open Services',view:'services'}]}}
  if(/topology|graph|system map|digital twin|blast radius|dependency/.test(t)){return{answer:`The live topology currently projects ${d.github.repos?.length||0} repositories across ${d.domains?.length||0} domains. It supports semantic zoom, relationship spotlighting, temporal activity horizons and source-coverage diff.`,links:[{label:'Open live topology',view:'topology'}]}}
  if(/evidence|vsr|fcr|cpvo|metric/.test(t)){return{answer:d.metrics?.length?`${d.metrics.length} latest metric samples are available. Unknown research metrics remain “—” rather than being inferred.`:'No external KPI samples have been ingested into this local evidence store yet. Unknown values remain “—”.',links:[{label:'Open Evidence',view:'verification'}]}}
  if(/next|risk|intelligence|recommend|priorit|what should|do next/.test(t)){const c=d.intelligence?.top;if(!c)return{answer:'The operational intelligence layer has no material ranked candidate right now. That is not a proof of health; it means no current source-backed signal crossed the display threshold.',links:[{label:'Open Intelligence',view:'intelligence'}]};return{answer:`Top ranked attention candidate: ${c.title}. Priority ${Math.round(c.priorityScore)}/100, risk score ${Math.round(c.riskScore*100)}%, confidence ${Math.round(c.confidence*100)}%. Recommended next step: ${c.recommendedAction}`,links:[{label:'Open Intelligence',view:'intelligence'},...(c.url?[{label:'Open source',url:c.url}]:[])]}}
  const repo=(d.github.repos||[]).find(r=>t.includes(r.name.toLowerCase()));if(repo)return{answer:`${repo.name} is classified under ${repo.domain}. Visibility: ${repo.visibility||'unknown'}. Last push: ${repo.pushedAt?ago(repo.pushedAt):'unobserved'}. Source: ${repo.source}.`,links:[{label:'Focus in topology',view:'topology',focus:`repo:${repo.name}`},{label:'Open repository',url:repo.htmlUrl},{label:'Filter repositories',view:'repositories',domain:repo.domain}]};return{answer:'I can answer from the local system reality: attention, recent changes, repositories, workflows/CI, service health, host telemetry, and evidence metrics. I will not invent state that is not in those sources.',links:[{label:'Open Activity',view:'activity'},{label:'Open Repositories',view:'repositories'}]}}
function assistantObjectHTML(o){const fields=Object.entries(o.fields||{}).slice(0,4),title=o.title||o.id||'Object',type=o.type||'object';return`<article class="assistant-object type-${esc(type)}" role="group" aria-label="${esc(type+': '+title)}"><div class="assistant-object-mark" aria-hidden="true">${o.type==='agent'?'◉':o.type==='workflow'?'✓':o.type==='repository'?'R':o.type==='typesafe-decision'?'J':'◇'}</div><div class="assistant-object-body"><div class="assistant-object-head"><b>${esc(title)}</b>${o.status?`<span class="source-chip ${['failure','blocked','critical'].includes(String(o.status).toLowerCase())?'attention':''}">${esc(o.status)}</span>`:''}</div>${o.subtitle?`<p>${esc(o.subtitle)}</p>`:''}${fields.length?`<div class="assistant-object-fields">${fields.map(([k,v])=>`<span>${esc(k)} <b>${esc(v||'—')}</b></span>`).join('')}</div>`:''}</div>${o.url?`<a href="${esc(safeURL(o.url))}" target="_blank" rel="noreferrer" aria-label="${esc('Open source for '+title)}">↗</a>`:''}</article>`}
function assistantActionHTML(a,i,stamp){if(a.kind==='url')return`<a href="${esc(safeURL(a.target))}" target="_blank" rel="noreferrer">${esc(a.label)} ↗</a>`;return`<button data-assistant-stamp="${stamp}" data-assistant-action="${i}">${esc(a.label)} →</button>`}
function activateAssistantAction(a){if(!a)return;if(a.kind==='view'){setView(a.target);return}if(a.kind==='focus'){setView('topology');setTimeout(()=>window.AGSpatial?.focus(a.target),120);return}if(a.kind==='url'){window.open(safeURL(a.target),'_blank','noopener,noreferrer')}}
function renderQueryThread(){const root=$('#queryThread');if(!root)return;root.innerHTML=S.queryHistory.map(x=>{const r=x.response||{answer:x.answer||'',actions:(x.links||[]).map(l=>({label:l.label,kind:l.url?'url':'view',target:l.url||l.view}))};const stamp=x.time.getTime();const objects=r.objects||[];const sources=r.sources||[];const caveats=r.caveats||[];return`<div class="query-card ${x.pending?'pending':''}"><div class="query-q"><span class="query-message">${esc(x.q)}</span><span class="query-time">${x.time.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span></div><div class="query-a">${x.pending?'<span class="assistant-thinking"><i></i><i></i><i></i></span>':esc(r.answer||'')}</div>${objects.length?`<div class="assistant-objects">${objects.map(assistantObjectHTML).join('')}</div>`:''}${!x.pending&&(r.actions||[]).length?`<div class="query-links">${(r.actions||[]).map((a,i)=>assistantActionHTML(a,i,stamp)).join('')}</div>`:''}${!x.pending&&(sources.length||caveats.length)?`<details class="assistant-provenance"><summary>${esc(r.mode||'grounded')} · ${Number.isFinite(+r.confidence)?Math.round(+r.confidence*100)+'% confidence':'source bounded'}</summary>${sources.length?`<div><b>Sources</b>${sources.map(v=>`<span>${esc(v)}</span>`).join('')}</div>`:''}${caveats.length?`<div><b>Boundary</b>${caveats.map(v=>`<span>${esc(v)}</span>`).join('')}</div>`:''}</details>`:''}</div>`}).join('');root.querySelectorAll('[data-assistant-action]').forEach(b=>b.onclick=()=>{const h=S.queryHistory.find(x=>String(x.time.getTime())===b.dataset.assistantStamp);activateAssistantAction(h?.response?.actions?.[+b.dataset.assistantAction])});}
function showQueryResult(q,answer,links=[]){S.queryHistory.unshift({q,time:new Date(),response:{answer,mode:'inspection',confidence:1,sources:[],objects:[],actions:links.map(l=>({label:l.label,kind:l.url?'url':'view',target:l.url||l.view})),caveats:[]}});S.queryHistory=S.queryHistory.slice(0,7);renderQueryThread()}
async function runQuery(q){const item={q,time:new Date(),pending:true,response:null};S.queryHistory.unshift(item);S.queryHistory=S.queryHistory.slice(0,7);renderQueryThread();window.AGVisual?.audio('tap');try{const r=await api('/api/assistant/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:q})});item.response=r;item.pending=false;S.assistant=S.data?.assistant||S.assistant;renderQueryThread();window.AGVisual?.audio('open')}catch(e){item.response={answer:`Assistant query failed: ${e.message}`,mode:'error',confidence:0,sources:[],objects:[],actions:[{label:'Open Connections',kind:'view',target:'connections'}],caveats:['No state was invented to fill the failed query.']};item.pending=false;renderQueryThread()}}
function paletteItems(q=''){const base=[{type:'view',label:'Now',sub:'Assistant, system pulse and live activity',view:'overview',icon:'●'},{type:'view',label:'Activity',sub:'GitHub, CI and agent events',view:'activity',icon:'↗'},{type:'view',label:'Topology',sub:'Live spatial digital twin and causal flow',view:'topology',icon:'◇'},{type:'view',label:'Agents & workers',sub:'WORKS runners and Agent Bridge heartbeats',view:'agents',icon:'◉'},{type:'view',label:'Intelligence',sub:'Adaptive evidence-backed attention ranking',view:'intelligence',icon:'◎'},{type:'view',label:'Systems',sub:'Nine operational domains',view:'domains',icon:'◇'},{type:'view',label:'Repositories',sub:'Organization inventory',view:'repositories',icon:'⌘'},{type:'view',label:'Evidence',sub:'Metrics and verification ledger',view:'verification',icon:'✓'},{type:'view',label:'Services & compute',sub:'HTTP probes and host telemetry',view:'services',icon:'◌'},{type:'view',label:'Connections',sub:'GitHub, WORKS, agents, Jev and assistant',view:'connections',icon:'⚙'}];const repos=(S.data?.github?.repos||[]).map(r=>({type:'repo',label:r.name,sub:r.domain,url:r.htmlUrl,icon:'R'}));const domains=(S.data?.domains||[]).map(d=>({type:'domain',label:d.name,sub:`${d.repoCount} repos · ${d.status}`,domain:d.name,icon:'D'}));const all=[...base,...repos,...domains], t=q.trim().toLowerCase();if(!t)return base.slice(0,8);return all.filter(x=>`${x.label} ${x.sub}`.toLowerCase().includes(t)).slice(0,12)}
let paletteSelected=0;function openPalette(){const panel=$('#palette'),trigger=document.activeElement;paletteSelected=0;panel.classList.remove('hidden');$('#paletteInput').value='';renderPalette();window.AGVisual?.decorate(panel);window.AGVisual?.activateDialog?.(panel,trigger,closePalette);queueMicrotask(()=>$('#paletteInput')?.focus())}function closePalette(){const panel=$('#palette');panel.classList.add('hidden');window.AGVisual?.deactivateDialog?.(panel)}function renderPalette(){const q=$('#paletteInput').value,items=paletteItems(q),root=$('#paletteResults'),input=$('#paletteInput');root._items=items;root.innerHTML=items.map((x,i)=>`<button type="button" id="palette-option-${i}" role="option" aria-selected="${i===paletteSelected}" class="palette-option ${i===paletteSelected?'selected':''}" data-index="${i}"><span class="pal-icon" aria-hidden="true">${esc(x.icon)}</span><span><span>${esc(x.label)}</span><small>${esc(x.sub)}</small></span><small>${esc(x.type)}</small></button>`).join('')+(q.trim()&&!items.length?`<button type="button" id="palette-option-query" role="option" aria-selected="true" class="palette-option selected" data-query="1"><span class="pal-icon" aria-hidden="true">⌕</span><span><span>Ask War Room</span><small>${esc(q)}</small></span><small>query</small></button>`:'');const selected=root.querySelector('.palette-option.selected');if(input){if(selected)input.setAttribute('aria-activedescendant',selected.id);else input.removeAttribute('aria-activedescendant')}root.querySelectorAll('.palette-option').forEach(el=>el.onclick=()=>activatePalette(el))}
function activatePalette(el){if(el.dataset.query){const q=$('#paletteInput').value;closePalette();setView('overview');runQuery(q);return}const item=$('#paletteResults')._items?.[+el.dataset.index];if(!item)return;if(item.view)setView(item.view);else if(item.url)window.open(safeURL(item.url),'_blank','noopener,noreferrer');else if(item.domain){setView('repositories');$('#repoDomainFilter').value=item.domain;renderRepos()}closePalette()}
async function loadWorksStatus(){try{S.works=await api('/api/works/connection');if($('#worksUrl'))$('#worksUrl').value=S.works.url||S.settings?.worksUrl||'';if($('#worksEnabled'))$('#worksEnabled').checked=S.works.enabled===true;if($('#worksBadge')){$('#worksBadge').textContent=S.works.configured?'Connected':S.works.enabled?'Waiting':'Not configured';$('#worksBadge').classList.toggle('neutral',!S.works.configured)}if($('#worksConnMsg'))$('#worksConnMsg').textContent=S.works.configured?`Live runner stream configured at ${S.works.url}.`:'Connect the canonical WORKS read-only UI/SSE surface.'}catch(e){if($('#worksConnMsg'))$('#worksConnMsg').textContent=e.message}}
async function loadAssistantStatus(){try{S.assistant=await api('/api/assistant/status');if(S.data)S.data.assistant=S.assistant;renderAssistantStatus()}catch{S.assistant=S.data?.assistant||{mode:'grounded-core',groundedCore:true};renderAssistantStatus()}}

async function refresh(silent=true){if(S.destroyed)return null;if(S.refreshInFlight){S.refreshQueued=true;S.refreshQueuedLoud=S.refreshQueuedLoud||!silent;return S.refreshInFlight}const run=(async()=>{try{const data=await api('/api/summary');if(S.destroyed)return null;S.data=data;S.lastRefreshError='';if(data.typeSafe?.configured)S.typesafe={...(S.typesafe||{}),configured:true,decision:data.typeSafe};render();if(!silent){banner('System reality refreshed.','ok');window.AGVisual?.audio('success')}return data}catch(e){S.lastRefreshError=e.message;if(!silent)banner(e.message);return null}})();S.refreshInFlight=run;try{return await run}finally{S.refreshInFlight=null;if(S.refreshQueued&&!S.destroyed){const loud=S.refreshQueuedLoud;S.refreshQueued=false;S.refreshQueuedLoud=false;queueMicrotask(()=>refresh(!loud))}}}
async function boot(){window.AGIcons?.hydrate();window.AGVisual?.init();window.AGSpatial?.init();const ses=await fetch('/api/session').then(r=>r.json());S.session=ses.session;$('#build').textContent=`v${ses.version||'1.6.14'}`;try{S.settings=await api('/api/settings');$('#orgInput').value=S.settings.githubOrg;$('#refreshInput').value=S.settings.refreshSeconds||60;$('#workflowCap').value=S.settings.workflowRepoCap||33;if($('#agentStaleSeconds'))$('#agentStaleSeconds').value=S.settings.agentStaleSeconds||45;if($('#typesafeAuto'))$('#typesafeAuto').checked=S.settings.typeSafeAuto!==false;if($('#typesafeInterval'))$('#typesafeInterval').value=S.settings.typeSafeMinIntervalSec||300;if($('#typesafeBudget'))$('#typesafeBudget').value=S.settings.typeSafeDailyBudget||60;if($('#assistantLocalModel'))$('#assistantLocalModel').checked=S.settings.assistantLocalModel!==false;if($('#assistantOllamaUrl'))$('#assistantOllamaUrl').value=S.settings.assistantOllamaUrl||'http://127.0.0.1:11434';if($('#assistantModel'))$('#assistantModel').value=S.settings.assistantModel||''}catch{}try{const c=await api('/api/github/connection');$('#githubBadge').textContent=c.configured?'Configured':'Not configured';$('#githubBadge').classList.toggle('neutral',!c.configured);$('#connectionMini').classList.toggle('good',c.configured)}catch{}await Promise.all([loadTypeSafeStatus(),loadWorksStatus(),loadAssistantStatus()]);await refresh();const hash=location.hash.slice(1);if(hash&&viewTitles[hash])setView(hash);connectStream();S.timers.push(setInterval(()=>refresh(true),30000),setInterval(renderClock,15000));renderClock();}
function connectStream(){S.eventSource?.close?.();const ev=new EventSource('/api/stream');S.eventSource=ev;const markLive=()=>{S.sseState='live';renderSidebar()};ev.addEventListener('ready',()=>{markLive();window.AGVisual?.pulse('ready');refresh(true)});ev.addEventListener('update',e=>{markLive();let kind='update';try{kind=JSON.parse(e.data)}catch{kind=String(e.data||'update').replaceAll('\"','')}window.AGVisual?.pulse(kind==='github-activity'?'arrival':kind==='agents'?'agent':'update');if(kind==='agents')window.AGVisual?.audio('open');refresh(true)});ev.addEventListener('typesafe',()=>{markLive();window.AGVisual?.pulse('decision');refresh(true)});ev.addEventListener('ping',()=>{markLive()});ev.onerror=()=>{S.sseState=ev.readyState===2?'offline':'reconnecting';renderSidebar()}}
function teardown(){if(S.destroyed)return;S.destroyed=true;S.eventSource?.close?.();S.eventSource=null;for(const id of S.timers)clearInterval(id);S.timers=[];window.AGSpatial?.destroy?.();window.AGVisual?.destroy?.()}
window.addEventListener('pagehide',teardown,{once:true});

$$('.nav').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-jump]').forEach(b=>b.onclick=()=>setView(b.dataset.jump));
$('#overviewFilter').onclick=e=>{const b=e.target.closest('button');if(!b)return;S.overviewFilter=b.dataset.filter;renderOverviewFilters();renderLiveFeed()};
$('#activityFilter').onclick=e=>{const b=e.target.closest('button');if(!b)return;S.activityFilter=b.dataset.filter;renderOverviewFilters();renderActivityView()};
$('#repoSearch').oninput=renderRepos;$('#repoDomainFilter').onchange=renderRepos;
$('#askForm').onsubmit=e=>{e.preventDefault();const q=$('#askInput').value.trim();if(!q)return;$('#askInput').value='';runQuery(q)};$$('[data-prompt]').forEach(b=>b.onclick=()=>runQuery(b.dataset.prompt));
$('#attentionBtn').onclick=()=>{setView('overview');$('#attention').scrollIntoView({behavior:'smooth',block:'center'})};
$('#syncBtn').onclick=async()=>{const b=$('#syncBtn');b.disabled=true;b.classList.add('sync-spinning');window.AGVisual?.audio('tap');try{await api('/api/github/sync',{method:'POST'});await refresh(false)}catch(e){banner(e.message)}finally{b.disabled=false;b.classList.remove('sync-spinning')}};
$('#probeBtn').onclick=async()=>{try{await api('/api/probes/run',{method:'POST'});await refresh(false)}catch(e){banner(e.message)}};
$('#saveGithub').onclick=async()=>{const token=$('#githubToken').value.trim();if(!token){$('#githubConnMsg').textContent='Enter a token first.';return}$('#githubConnMsg').textContent='Validating…';try{const r=await api('/api/github/connection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});$('#githubToken').value='';$('#githubBadge').textContent='Configured';$('#githubBadge').classList.remove('neutral');$('#githubConnMsg').textContent=`Connected as ${r.identity}. Encrypted with ${r.storage}.`;await api('/api/github/sync',{method:'POST'});await refresh()}catch(e){$('#githubConnMsg').textContent=e.message}};
$('#deleteGithub').onclick=async()=>{try{await api('/api/github/connection',{method:'DELETE'});$('#githubBadge').textContent='Not configured';$('#githubBadge').classList.add('neutral');$('#githubConnMsg').textContent='GitHub credential removed.';await refresh()}catch(e){$('#githubConnMsg').textContent=e.message}};
$('#saveTypesafe').onclick=async()=>{const apiKey=$('#typesafeApiKey').value.trim();if(!apiKey){$('#typesafeConnMsg').textContent='Enter an API key first.';return}$('#typesafeConnMsg').textContent='Encrypting connection…';try{await api('/api/typesafe/connection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey})});$('#typesafeApiKey').value='';$('#typesafeConnMsg').textContent='TypeSafe key stored in the Windows credential boundary. Native Jev evaluation is now armed and runs on bounded state changes.';await loadTypeSafeStatus();setTimeout(()=>refresh(true),450);window.AGVisual?.audio('success')}catch(e){$('#typesafeConnMsg').textContent=e.message}};
$('#deleteTypesafe').onclick=async()=>{try{await api('/api/typesafe/connection',{method:'DELETE'});$('#typesafeConnMsg').textContent='TypeSafe credential removed.';await loadTypeSafeStatus()}catch(e){$('#typesafeConnMsg').textContent=e.message}};
$('#saveWorks').onclick=async()=>{const url=$('#worksUrl').value.trim(),token=$('#worksToken').value.trim(),enabled=$('#worksEnabled').checked;if(!url){$('#worksConnMsg').textContent='Enter the WORKS base URL first.';return}$('#worksConnMsg').textContent='Validating WORKS read-only surface…';try{const r=await api('/api/works/connection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url,token,enabled})});$('#worksToken').value='';$('#worksBadge').textContent='Connected';$('#worksBadge').classList.remove('neutral');$('#worksConnMsg').textContent=`Connected read-only SSE: ${r.stream}`;S.settings={...(S.settings||{}),worksEnabled:enabled,worksUrl:r.url};await loadWorksStatus();await refresh(true);window.AGVisual?.audio('success')}catch(e){$('#worksConnMsg').textContent=e.message}};
$('#deleteWorks').onclick=async()=>{try{await api('/api/works/connection',{method:'DELETE'});$('#worksBadge').textContent='Not configured';$('#worksBadge').classList.add('neutral');$('#worksConnMsg').textContent='WORKS connection removed.';S.settings={...(S.settings||{}),worksEnabled:false};await loadWorksStatus();await refresh(true)}catch(e){$('#worksConnMsg').textContent=e.message}};
$('#revealAgentToken').onclick=async()=>{try{const r=await api('/api/agents/bridge?reveal=1');$('#agentTokenOut').classList.remove('hidden');$('#agentTokenOut').textContent=r.token;$('#agentTokenOut').setAttribute('aria-label','Agent Bridge bearer token')}catch(e){banner(e.message)}};
$('#rotateAgentToken').onclick=async()=>{if(!confirm('Rotate the Agent Bridge token? Existing agents will stop reporting until reconfigured.'))return;try{const r=await api('/api/agents/bridge',{method:'POST'});$('#agentTokenOut').classList.remove('hidden');$('#agentTokenOut').textContent=r.token;banner('Agent Bridge token rotated.','ok')}catch(e){banner(e.message)}};
$('#agentRefresh').onclick=()=>refresh(false);
$('#typesafeEvaluate').onclick=evaluateTypeSafe;
$('#routineSync').onclick=()=>$('#syncBtn').click();
$('#routineProbe').onclick=()=>{setView('services');setTimeout(()=>$('#probeBtn')?.click(),120)};
$('#composerPlus').onclick=()=>openPalette();

$('#saveSettings').onclick=async()=>{const next={...S.settings,githubOrg:$('#orgInput').value.trim(),refreshSeconds:+$('#refreshInput').value,workflowRepoCap:+$('#workflowCap').value,agentStaleSeconds:+($('#agentStaleSeconds')?.value||45),typeSafeAuto:$('#typesafeAuto')?.checked??true,typeSafeMinIntervalSec:+($('#typesafeInterval')?.value||300),typeSafeDailyBudget:+($('#typesafeBudget')?.value||60),assistantLocalModel:$('#assistantLocalModel')?.checked??true,assistantOllamaUrl:$('#assistantOllamaUrl')?.value.trim()||'http://127.0.0.1:11434',assistantModel:$('#assistantModel')?.value.trim()||''};try{S.settings=await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(next)});S.assistant=null;banner('Settings saved. Live sources will adopt the new policy.','ok');await loadAssistantStatus();setTimeout(()=>banner(''),1800)}catch(e){banner(e.message)}};
$('#exitBtn').onclick=async()=>{try{await api('/api/shutdown',{method:'POST'})}catch{}window.close()};
$('#commandBtn').onclick=()=>{window.AGVisual?.audio('open');openPalette()};$('#paletteInput').oninput=()=>{paletteSelected=0;renderPalette()};$('#palette').onclick=e=>{if(e.target===$('#palette'))closePalette()};
$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#sidebarToggle').onclick=()=>{if(innerWidth<650)$('#sidebar').classList.toggle('open')};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette();return}if(e.altKey&&['1','2','3','4','5','6','7','8','9'].includes(e.key)){e.preventDefault();setView(['overview','activity','topology','agents','intelligence','domains','repositories','verification','services'][+e.key-1]);return}if($('#palette').classList.contains('hidden'))return;if(e.key==='Escape'){closePalette();return}const opts=$$('#paletteResults .palette-option');if(e.key==='ArrowDown'){e.preventDefault();paletteSelected=Math.min(opts.length-1,paletteSelected+1);renderPalette()}if(e.key==='ArrowUp'){e.preventDefault();paletteSelected=Math.max(0,paletteSelected-1);renderPalette()}if(e.key==='Enter'){e.preventDefault();const el=$$('#paletteResults .palette-option')[paletteSelected];if(el)activatePalette(el)}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(viewTitles[h]&&h!==S.view)setView(h)});
window.addEventListener('warroom:open-domain',e=>{setView('repositories');if($('#repoDomainFilter')){$('#repoDomainFilter').value=e.detail;renderRepos()}});
